package com.parvnigam.careerbridge;

import jakarta.validation.Valid;
import java.time.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.http.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.transaction.annotation.Transactional;
import jakarta.servlet.http.HttpServletRequest;

@RestController @RequestMapping("/api")
public class ApiController {
    final EmailVerification verification;final Platform p;final NotificationService notices;final jakarta.persistence.EntityManager entityManager;final Store r;final ResumeService resumes;final CareerService career;final JwtEncoder encoder;final PasswordEncoder passwords;
    final Map<String,Attempt> attempts=new ConcurrentHashMap<>();
    record Attempt(int count,Instant until){}
    public ApiController(EmailVerification verification,Platform p,Store r,ResumeService resumes,CareerService career,JwtEncoder encoder,PasswordEncoder passwords,NotificationService notices,jakarta.persistence.EntityManager entityManager){this.verification=verification;this.notices=notices;this.entityManager=entityManager;this.p=p;this.r=r;this.resumes=resumes;this.career=career;this.encoder=encoder;this.passwords=passwords;}
    @GetMapping("/public/universities") Object universities(){return r.universities().findAll();}
    @GetMapping("/public/jobs") Object publicJobs(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String type,@RequestParam(defaultValue="")String mode){return p.jobs(null,q,type,mode,false);}
    @GetMapping("/public/jobs/{id}") Object publicJob(@PathVariable Long id){Model.Job j=p.job(id);if(j.universityId!=null||!p.active(j))throw Platform.fail(404,"Job not found");return p.jobView(j,null);}
    @GetMapping("/public/info") Object info(){return Platform.map("name","CareerBridge","roles",List.of("STUDENT","RECRUITER","PLACEMENT_OFFICER","ADMIN"),"jobs",r.jobs().findAll().stream().filter(p::active).count(),"students",r.accounts().findAll().stream().filter(a->a.role==Model.Role.STUDENT&&a.enabled&&!Boolean.FALSE.equals(a.emailVerified)).count());}
    @PostMapping("/auth/login") Object login(@Valid @RequestBody Inputs.Login d,HttpServletRequest request){String email=d.email().trim().toLowerCase();String key=request.getRemoteAddr()+":"+email;Instant now=Instant.now();attempts.entrySet().removeIf(e->e.getValue().until().isBefore(now));Attempt prev=attempts.get(key);if(prev!=null&&prev.count()>=5)throw Platform.fail(429,"Too many attempts. Try again in 15 minutes");
        Model.Account a=r.accounts().findByEmail(email).orElse(null);if(a==null||!a.enabled||!passwords.matches(d.password(),a.passwordHash)){attempts.put(key,new Attempt(prev==null?1:prev.count()+1,now.plusSeconds(900)));throw Platform.fail(401,"Invalid email or password");}attempts.remove(key);if(Boolean.FALSE.equals(a.emailVerified))throw Platform.fail(403,"Verify your email before signing in. Use Resend verification email if you need a new link.");return session(a);}
    @PostMapping("/auth/register") @ResponseStatus(HttpStatus.CREATED) @Transactional Object register(@Valid @RequestBody Inputs.Register d,HttpServletRequest request){verification.limit(request.getRemoteAddr(),"register");if(d.role()!=Model.Role.STUDENT&&d.role()!=Model.Role.RECRUITER)throw Platform.fail(403,"Staff accounts are created by an administrator");Model.Account a=createAccount(d);a.emailVerified=false;r.accounts().save(a);verification.issue(a);return Platform.map("verificationRequired",true,"message","Account created. Check your email to verify your account.");}
    @PostMapping("/auth/verify-email") Object verifyEmail(@Valid @RequestBody Inputs.VerifyEmail d,HttpServletRequest request){verification.limit(request.getRemoteAddr(),"verify");verification.verify(d.token());return Platform.map("message","Email verified. You can now sign in.");}
    @PostMapping("/auth/resend-verification") Object resendVerification(@Valid @RequestBody Inputs.VerificationEmail d,HttpServletRequest request){verification.limit(request.getRemoteAddr(),"resend");verification.resend(d.email());return Platform.map("message","If this account needs verification, a link has been sent. Wait at least 60 seconds before requesting another.");}
    Model.Account createAccount(Inputs.Register d){if(!d.password().matches("(?s)(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{10,72}"))throw Platform.fail(400,"Use 10–72 characters including uppercase, lowercase and a number");
        String email=d.email().trim().toLowerCase();if(r.accounts().findByEmail(email).isPresent())throw Platform.fail(409,"This email is already registered");
        if((d.role()==Model.Role.STUDENT||d.role()==Model.Role.PLACEMENT_OFFICER)&&(d.universityId()==null||!r.universities().existsById(d.universityId())))throw Platform.fail(400,"Select a valid university");
        Model.Account a=new Model.Account();a.email=email;a.name=d.name().trim();a.passwordHash=passwords.encode(d.password());a.role=d.role();a.universityId=d.universityId();a.department=Platform.clean(d.department());a.graduationYear=d.graduationYear()==null?2028:d.graduationYear();r.accounts().save(a);
        if(a.role==Model.Role.STUDENT){Model.Profile profile=new Model.Profile();profile.userId=a.id;r.profiles().save(profile);}if(a.role==Model.Role.RECRUITER){Model.Company c=new Model.Company();c.userId=a.id;r.companies().save(c);}return a;}
    Object session(Model.Account a){return Platform.map("token",SecurityConfig.token(encoder,a),"user",p.user(a));}
    @GetMapping("/auth/me") Object me(@AuthenticationPrincipal Jwt jwt){return p.user(p.actor(jwt));}
    @PostMapping("/auth/logout") Object logout(@AuthenticationPrincipal Jwt jwt){Model.Account a=p.actor(jwt);a.authVersion++;r.accounts().save(a);return Platform.map("ok",true);}
    @PatchMapping("/account") Object account(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,String>d){Model.Account a=p.actor(jwt);String name=d.get("name");if(name!=null){if(name.isBlank()||name.length()>80)throw Platform.fail(400,"Name must be 1–80 characters");a.name=name.trim();}String pw=d.get("newPassword");if(pw!=null&&!pw.isBlank()){if(!passwords.matches(d.getOrDefault("currentPassword",""),a.passwordHash))throw Platform.fail(400,"Current password is incorrect");if(!pw.matches("(?s)(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{10,72}"))throw Platform.fail(400,"New password needs 10–72 characters, uppercase, lowercase and a number");a.passwordHash=passwords.encode(pw);a.authVersion++;}r.accounts().save(a);return session(a);}
    @GetMapping("/dashboard") Object dashboard(@AuthenticationPrincipal Jwt jwt){return p.dashboard(p.actor(jwt));}
    @GetMapping("/jobs") Object jobs(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String type,@RequestParam(defaultValue="")String mode){return p.jobs(p.actor(jwt),q,type,mode,false);}
    @GetMapping("/jobs/{id}") Object job(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Model.Account a=p.actor(jwt);Model.Job j=p.job(id);if(!p.canSee(a,j))throw Platform.fail(403,"This opening is for another university");return p.jobView(j,a);}
    @GetMapping("/student/profile") Object profile(@AuthenticationPrincipal Jwt jwt){return p.fullProfile(p.actor(jwt));}
    @PutMapping("/student/profile") Object updateProfile(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Profile d){Model.Account a=p.actor(jwt);p.updateProfile(a,d);return p.fullProfile(a);}
    @PutMapping("/student/academics") Object updateAcademics(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Academics d){Model.Account a=p.actor(jwt);p.updateAcademics(a,d);return p.fullProfile(a);}
    @PostMapping("/student/projects") Object project(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Project d){Model.Project x=new Model.Project();x.userId=p.actor(jwt).id;x.title=d.title();x.description=d.description();x.stack=d.stack();x.repositoryUrl=safeUrl(d.repositoryUrl());x.liveUrl=safeUrl(d.liveUrl());return r.projects().save(x);}
    @DeleteMapping("/student/projects/{id}") Object deleteProject(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Model.Project x=r.projects().findById(id).orElseThrow(()->Platform.fail(404,"Project not found"));own(p.actor(jwt).id,x.userId);r.projects().delete(x);return Platform.map("ok",true);}
    @PostMapping("/student/education") Object education(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Education d){Model.Education x=new Model.Education();x.userId=p.actor(jwt).id;x.institution=d.institution();x.qualification=d.qualification();x.passingYear=d.passingYear();x.grade=d.grade();return r.educations().save(x);}
    @DeleteMapping("/student/education/{id}") Object deleteEducation(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Model.Education x=r.educations().findById(id).orElseThrow(()->Platform.fail(404,"Education not found"));own(p.actor(jwt).id,x.userId);r.educations().delete(x);return Platform.map("ok",true);}
    @PostMapping("/student/experience") Object experience(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Experience d){Model.Experience x=new Model.Experience();x.userId=p.actor(jwt).id;x.company=d.company();x.title=d.title();x.duration=d.duration();x.description=d.description();return r.experiences().save(x);}
    @DeleteMapping("/student/experience/{id}") Object deleteExperience(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Model.Experience x=r.experiences().findById(id).orElseThrow(()->Platform.fail(404,"Experience not found"));own(p.actor(jwt).id,x.userId);r.experiences().delete(x);return Platform.map("ok",true);}
    @GetMapping("/student/recommendations") Object recommendations(@AuthenticationPrincipal Jwt jwt){Model.Account a=p.actor(jwt);return career.rank(a,p.recommendations(a));}
    @GetMapping("/student/learning") Object learning(@AuthenticationPrincipal Jwt jwt){return career.learning(p.recommendations(p.actor(jwt)));}
    @GetMapping("/student/saved") Object saved(@AuthenticationPrincipal Jwt jwt){Model.Account a=p.actor(jwt);return r.saves().findByStudentId(a.id).stream().map(x->p.jobView(p.job(x.jobId),a)).toList();}
    @PostMapping("/student/saved/{id}") Object save(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Model.Account a=p.actor(jwt);Model.Job j=p.job(id);if(!p.canSee(a,j))throw Platform.fail(403,"This opening is for another university");if(r.saves().findByStudentIdAndJobId(a.id,id).isEmpty()){Model.SavedJob x=new Model.SavedJob();x.studentId=a.id;x.jobId=id;r.saves().save(x);}return Platform.map("ok",true);}
    @DeleteMapping("/student/saved/{id}") Object unsave(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Model.Account a=p.actor(jwt);r.saves().findByStudentIdAndJobId(a.id,id).ifPresent(r.saves()::delete);return Platform.map("ok",true);}
    @GetMapping("/student/applications") Object applications(@AuthenticationPrincipal Jwt jwt){Model.Account a=p.actor(jwt);return r.applications().findByStudentIdOrderByCreatedAtDesc(a.id).stream().map(x->p.applicationView(x,a)).toList();}
    @PostMapping("/student/applications") @ResponseStatus(HttpStatus.CREATED) Object apply(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Apply d){Model.Account a=p.actor(jwt);return p.applicationView(p.apply(a,d),a);}
    @PostMapping("/student/applications/{id}/withdraw") Object withdraw(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){p.withdraw(p.actor(jwt),id);return Platform.map("ok",true);}
    @GetMapping("/student/resumes") Object resumeList(@AuthenticationPrincipal Jwt jwt){return r.resumes().findByUserIdOrderByCreatedAtDesc(p.actor(jwt).id).stream().map(resumes::view).toList();}
    @PostMapping("/student/resumes") Object upload(@AuthenticationPrincipal Jwt jwt,@RequestParam("file")MultipartFile file)throws Exception{try{return resumes.view(resumes.upload(p.actor(jwt),file));}catch(org.springframework.web.server.ResponseStatusException e){throw e;}catch(Exception e){throw Platform.fail(400,"Could not parse this resume. Use a valid text-based PDF, DOCX or TXT file");}}
    @DeleteMapping("/student/resumes/{id}") Object deleteResume(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id)throws Exception{resumes.delete(p.actor(jwt),id);return Platform.map("ok",true);}
    @GetMapping("/resumes/{id}/download") Object download(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Model.Resume v=resumes.authorized(p.actor(jwt),id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(v.mediaType)).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(v.filename,java.nio.charset.StandardCharsets.UTF_8).build().toString()).body(new FileSystemResource(resumes.path(v)));}
    @PostMapping("/student/coding/sync") Object coding(@AuthenticationPrincipal Jwt jwt){return career.github(p.actor(jwt));}
    @GetMapping("/student/practice") Object practices(@AuthenticationPrincipal Jwt jwt){return r.mocks().findByUserIdOrderByCreatedAtDesc(p.actor(jwt).id).stream().map(career::mockView).toList();}
    @PostMapping("/student/practice") Object practice(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Mock d){return career.mockView(career.start(p.actor(jwt),d));}
    @PostMapping("/student/practice/{id}/submit") Object submit(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Map<String,List<String>>d){return career.mockView(career.submit(p.actor(jwt),id,d.getOrDefault("answers",List.of())));}
    @GetMapping("/recruiter/company") Object company(@AuthenticationPrincipal Jwt jwt){return r.companies().findByUserId(p.actor(jwt).id).orElseThrow();}
    @PutMapping("/recruiter/company") Object companySave(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Company d){Model.Company c=r.companies().findByUserId(p.actor(jwt).id).orElseThrow();c.name=d.name();c.website=safeUrl(d.website());c.location=d.location();c.description=d.description();return r.companies().save(c);}
    @GetMapping("/recruiter/jobs") Object ownJobs(@AuthenticationPrincipal Jwt jwt){return p.jobs(p.actor(jwt),"","","",true);}
    @PostMapping("/recruiter/jobs") @ResponseStatus(HttpStatus.CREATED) Object createJob(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Job d){Model.Account a=p.actor(jwt);return p.jobView(p.saveJob(a,null,d),a);}
    @PutMapping("/recruiter/jobs/{id}") Object editJob(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody Inputs.Job d){Model.Account a=p.actor(jwt);return p.jobView(p.saveJob(a,id,d),a);}
    @PatchMapping("/recruiter/jobs/{id}/status") Object jobStatus(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Map<String,String>d){Model.Account a=p.actor(jwt);String status=d.get("status");if(!Set.of("ACTIVE","PAUSED","CLOSED").contains(status))throw Platform.fail(400,"Invalid job status");Model.Job j=p.ownJob(a,id);j.status=status;r.jobs().save(j);p.audit(a,"JOB_STATUS",id.toString(),status);return p.jobView(j,a);}
    @GetMapping("/recruiter/applications") Object recruiterApplications(@AuthenticationPrincipal Jwt jwt){return p.recruiterApps(p.actor(jwt));}
    @PatchMapping("/recruiter/applications/{id}") Object stage(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody Inputs.Stage d){p.stage(p.actor(jwt),id,d);return Platform.map("ok",true);}
    @GetMapping("/recruiter/candidates") Object candidates(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="")String q,@RequestParam(required=false)Long jobId){return p.candidates(p.actor(jwt),q,jobId);}
    @PostMapping("/recruiter/candidates/{id}/invite") Object invite(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Map<String,Long>d){Model.Account recruiter=p.actor(jwt);Model.Job j=p.ownJob(recruiter,d.get("jobId"));Model.Account student=r.accounts().findById(id).orElseThrow(()->Platform.fail(404,"Student not found"));if(!student.enabled||Boolean.FALSE.equals(student.emailVerified)||student.role!=Model.Role.STUDENT||!p.profile(id).visibleToRecruiters||!p.active(j)||!p.canSee(student,j))throw Platform.fail(400,"This candidate cannot be invited to this opening");Eligibility.Report eligibility=Eligibility.assess(student,p.profile(id),j);if(!eligibility.eligible())throw Platform.fail(400,eligibility.blockedMessage());notices.send(id,"Invitation to apply",j.companyName+" invited you to apply for "+j.title,"/jobs");return Platform.map("ok",true);}
    @GetMapping("/interviews") Object interviews(@AuthenticationPrincipal Jwt jwt){Model.Account a=p.actor(jwt);return (a.role==Model.Role.RECRUITER?r.interviews().findByRecruiterIdOrderByScheduledAtAsc(a.id):r.interviews().findByStudentIdOrderByScheduledAtAsc(a.id)).stream().map(i->Platform.map("id",i.id,"scheduledAt",i.scheduledAt,"durationMinutes",i.durationMinutes,"meetingUrl",i.meetingUrl,"instructions",i.instructions,"status",i.status,"job",p.job(r.applications().findById(i.applicationId).orElseThrow().jobId).title,"student",r.accounts().findById(i.studentId).orElseThrow().name)).toList();}
    @PostMapping("/recruiter/applications/{id}/interview") @Transactional Object schedule(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody Inputs.Interview d){Model.Account recruiter=p.actor(jwt);Model.Application a=r.applications().findById(id).orElseThrow(()->Platform.fail(404,"Application not found"));p.ownJob(recruiter,a.jobId);java.util.stream.Stream.of(recruiter.id,a.studentId).sorted().forEach(accountId->entityManager.find(Model.Account.class,accountId,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE));if(a.status!=Model.Stage.SHORTLISTED&&a.status!=Model.Stage.INTERVIEW)throw Platform.fail(400,"Shortlist the applicant before scheduling an interview");
        Instant end=d.scheduledAt().plusSeconds(d.durationMinutes()*60L);boolean overlap=r.interviews().findAll().stream().filter(i->i.status.equals("SCHEDULED")&&(i.studentId.equals(a.studentId)||i.recruiterId.equals(recruiter.id))).anyMatch(i->i.scheduledAt.isBefore(end)&&i.scheduledAt.plusSeconds(i.durationMinutes*60L).isAfter(d.scheduledAt()));if(overlap)throw Platform.fail(409,"The recruiter or student already has an interview during this time");
        if(a.status==Model.Stage.SHORTLISTED)p.stage(recruiter,id,new Inputs.Stage(Model.Stage.INTERVIEW,"Interview scheduled"));Model.Interview i=new Model.Interview();i.applicationId=id;i.recruiterId=recruiter.id;i.studentId=a.studentId;i.scheduledAt=d.scheduledAt();i.durationMinutes=d.durationMinutes();i.meetingUrl=safeUrl(d.meetingUrl());i.instructions=d.instructions();r.interviews().save(i);notices.send(a.studentId,"Interview scheduled",p.job(a.jobId).title+" at "+i.scheduledAt,"/interviews");return i;}
    @PatchMapping("/recruiter/interviews/{id}") Object interviewStatus(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Map<String,String>d){Model.Account a=p.actor(jwt);Model.Interview i=r.interviews().findById(id).orElseThrow(()->Platform.fail(404,"Interview not found"));own(a.id,i.recruiterId);String status=d.get("status");if(!Set.of("COMPLETED","CANCELLED").contains(status))throw Platform.fail(400,"Choose completed or cancelled");i.status=status;r.interviews().save(i);notices.send(i.studentId,"Interview update",p.job(r.applications().findById(i.applicationId).orElseThrow().jobId).title+": "+status,"/interviews");return i;}
    @GetMapping("/notifications") Object notices(@AuthenticationPrincipal Jwt jwt){return r.notices().findByUserIdOrderByCreatedAtDesc(p.actor(jwt).id).stream().limit(100).toList();}
    @PatchMapping("/notifications/{id}") Object readNotice(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Model.Notice n=r.notices().findById(id).orElseThrow(()->Platform.fail(404,"Notification not found"));own(p.actor(jwt).id,n.userId);n.read=true;r.notices().save(n);return n;}
    @GetMapping("/placement/analytics") Object placement(@AuthenticationPrincipal Jwt jwt,@RequestParam(required=false)Integer year,@RequestParam(defaultValue="")String department){return p.placement(p.actor(jwt),year,department);}
    @GetMapping("/placement/jobs") Object placementJobs(@AuthenticationPrincipal Jwt jwt){return p.jobs(p.actor(jwt),"","","",false);}
    @PostMapping("/placement/announcements") Object announcement(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,String>d){Model.Account actor=p.actor(jwt);String title=d.getOrDefault("title","").trim(),message=d.getOrDefault("message","").trim();if(title.isBlank()||title.length()>120||message.isBlank()||message.length()>4000)throw Platform.fail(400,"Provide a title under 120 characters and a message under 4000 characters");List<Model.Account> targets=p.scopedStudents(actor,null,"");targets.forEach(a->notices.send(a.id,title,message,"/notifications"));p.audit(actor,"ANNOUNCEMENT",String.valueOf(actor.universityId),title);return Platform.map("recipients",targets.size());}
    @GetMapping("/placement/export") Object export(@AuthenticationPrincipal Jwt jwt,@RequestParam(required=false)Integer year,@RequestParam(defaultValue="")String department){
        Model.Account actor=p.actor(jwt);Set<Long> placed=r.applications().findAll().stream().filter(a->a.status==Model.Stage.HIRED).map(a->a.studentId).collect(java.util.stream.Collectors.toSet());
        StringBuilder output=new StringBuilder("Name,Email,Department,Graduation Year,CGPA (out of 10),10th Institution,10th Board,10th Passing Year,10th Result,12th or Diploma,Secondary Institution,Secondary Board,Secondary Passing Year,Secondary Result,College Institution,Degree,Current Semester,Active Backlogs,Cleared Backlogs,Gap Years,Placed\r\n");
        for(Model.Account a:p.scopedStudents(actor,year,department)){
            Model.Profile profile=p.profile(a.id);Model.Academics x=profile.academics==null?new Model.Academics():profile.academics;
            Object[] values={a.name,a.email,a.department,a.graduationYear,profile.cgpa,x.tenthInstitution,x.tenthBoard,x.tenthYear,Platform.schoolResult(x,true),x.secondaryQualification,x.secondaryInstitution,x.secondaryBoard,x.secondaryYear,Platform.schoolResult(x,false),x.collegeInstitution,x.degree,x.currentSemester,x.activeBacklogs,x.clearedBacklogs,x.gapYears,placed.contains(a.id)?"Yes":"No"};
            output.append(Arrays.stream(values).map(v->csv(v==null?"":v.toString())).collect(java.util.stream.Collectors.joining(","))).append("\r\n");
        }
        return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=placement-report.csv").body(output.toString());
    }
    @GetMapping("/admin/users") Object users(@AuthenticationPrincipal Jwt jwt){p.actor(jwt);return r.accounts().findAll().stream().map(p::user).toList();}
    @PostMapping("/admin/users") @ResponseStatus(HttpStatus.CREATED) @Transactional Object createUser(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Inputs.Register d){Model.Account admin=p.actor(jwt);Model.Account a=createAccount(d);p.audit(admin,"ACCOUNT_CREATED",a.id.toString(),a.role.name());return p.user(a);}
    @PatchMapping("/admin/users/{id}") Object toggle(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Map<String,Boolean>d){Model.Account admin=p.actor(jwt);if(admin.id.equals(id))throw Platform.fail(400,"You cannot disable your own administrator account");Model.Account a=r.accounts().findById(id).orElseThrow(()->Platform.fail(404,"Account not found"));a.enabled=d.getOrDefault("enabled",a.enabled);a.authVersion++;r.accounts().save(a);p.audit(admin,"ACCOUNT_STATUS",id.toString(),String.valueOf(a.enabled));return p.user(a);}
    @GetMapping("/admin/universities") Object adminUniversities(@AuthenticationPrincipal Jwt jwt){p.actor(jwt);return r.universities().findAll();}
    @PostMapping("/admin/universities") Object university(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,String>d){Model.Account a=p.actor(jwt);String name=d.getOrDefault("name","").trim();if(name.isBlank()||name.length()>150)throw Platform.fail(400,"Enter a university name under 150 characters");Model.University u=new Model.University();u.name=name;u.city=Platform.clean(d.get("city"));r.universities().save(u);p.audit(a,"UNIVERSITY_CREATED",u.id.toString(),u.name);return u;}
    @GetMapping("/admin/audit") Object audit(@AuthenticationPrincipal Jwt jwt){p.actor(jwt);return r.audits().findAll().stream().sorted(Comparator.comparing((Model.Audit a)->a.createdAt).reversed()).limit(100).toList();}
    @GetMapping("/admin/system") Object system(@AuthenticationPrincipal Jwt jwt){p.actor(jwt);return Platform.map("accounts",r.accounts().count(),"jobs",r.jobs().count(),"applications",r.applications().count(),"universities",r.universities().count(),"matching","Explainable weighted skills, CGPA, experience and location","resumeStorage","Private local filesystem","aiServiceConfigured",!career.aiUrl.isBlank(),"redisConfigured",career.cacheEnabled);}
    static void own(Long actor,Long owner){if(!actor.equals(owner))throw Platform.fail(403,"This record belongs to another account");}
    static String safeUrl(String value){String url=Platform.clean(value);if(url.isBlank())return "";try{java.net.URI uri=java.net.URI.create(url);if(!Set.of("https","http").contains(uri.getScheme())||uri.getHost()==null)throw new IllegalArgumentException();return url;}catch(Exception e){throw Platform.fail(400,"Links must be valid HTTP or HTTPS URLs");}}
    static String csv(String value){String s=Platform.clean(value);if(s.matches("^[=+@-].*"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
}
